                },
            rids_match(
                flat_combiner.value().get_Responding_0(),
                request_ids@,
                thread_idx as nat,
                flat_combiner.value().get_Responding_0().len(),
                resp_idx as nat,
                request_ids@.len(),
            ),
        decreases num_registered_threads - thread_idx
    {
        proof {
            rids_match_pop(
                flat_combiner.value().get_Responding_0(),
                request_ids@,
                thread_idx as nat,
                flat_combiner.value().get_Responding_0().len(),
